-- NET-UX3A | ISTAT 2026 reference import and governed city+province reconciliation.
-- Source: https://www.istat.it/storage/codici-unita-amministrative/Elenco-comuni-italiani.xlsx
-- 7894 current municipalities as at 2026-02-21. CC BY 4.0; ISTAT attribution required.
-- No reference rows are generated by this migration: they come from a validated official file.
alter table public.network_it_municipalities
  add column if not exists is_current boolean not null default true;
create index if not exists network_it_municipalities_current_name_province_idx
 on public.network_it_municipalities(municipality_normalized,province_code)
 where is_current;

create table if not exists public.network_it_istat_import_batches (
  id uuid primary key default gen_random_uuid(),
  source_url text not null check(source_url='https://www.istat.it/storage/codici-unita-amministrative/Elenco-comuni-italiani.xlsx'),
  file_sha256 text not null check(file_sha256 ~ '^[0-9a-f]{64}$'),
  reference_date date not null check(reference_date >= '2026-02-21'),
  expected_count integer not null check(expected_count=7894),
  status text not null default 'staging' check(status in ('staging','activated')),
  created_at timestamptz not null default now(),
  activated_at timestamptz,
  unique(file_sha256,reference_date)
);
create table if not exists public.network_it_istat_import_staging (
  batch_id uuid not null references public.network_it_istat_import_batches(id) on delete restrict,
  istat_code text not null check(istat_code ~ '^[0-9]{6}$'),
  municipality_name text not null,
  municipality_normalized text not null,
  province_code text not null check(province_code ~ '^[A-Z]{2}$'),
  province_name text not null,
  region_code text not null check(region_code ~ '^(0[1-9]|1[0-9]|20)$'),
  region_name text not null,
  primary key(batch_id,istat_code)
);
create index if not exists network_it_istat_import_staging_batch_idx
  on public.network_it_istat_import_staging(batch_id);
alter table public.network_it_istat_import_batches enable row level security;
alter table public.network_it_istat_import_staging enable row level security;
revoke all on public.network_it_istat_import_batches from public,anon,authenticated;
revoke all on public.network_it_istat_import_staging from public,anon,authenticated;
grant select,insert on public.network_it_istat_import_batches to service_role;
grant select,insert on public.network_it_istat_import_staging to service_role;

-- Service-role-only, SECURITY INVOKER: satisfies existing HP13 definer allowlist.
-- Transaction boundary ensures incomplete imports NEVER change active geography.
create or replace function public.netux3a_activate_istat_import(p_batch_id uuid)
returns jsonb language plpgsql security invoker set search_path=''
as $$
declare
  v_batch public.network_it_istat_import_batches%rowtype;
  v_rows integer;
  v_regions integer;
begin
  perform pg_advisory_xact_lock(hashtext('NETUX3A_ISTAT_ACTIVATION'));
  select * into v_batch from public.network_it_istat_import_batches
  where id=p_batch_id for update;
  if not found then raise exception 'ISTAT import batch not found' using errcode='P0002'; end if;
  if v_batch.status='activated' then
    return jsonb_build_object('status','already_activated','batch_id',p_batch_id);
  end if;
  select count(*),count(distinct region_code)
    into v_rows,v_regions
  from public.network_it_istat_import_staging where batch_id=p_batch_id;
  if v_rows<>7894 or v_regions<>20 or v_rows<>v_batch.expected_count then
    raise exception 'ISTAT batch incomplete: % rows / % regions',v_rows,v_regions using errcode='22023';
  end if;
  if not exists(select 1 from public.network_it_istat_import_staging
                where batch_id=p_batch_id
                  and lower(municipality_name)='castegnero nanto'
                  and region_code='05'
                  and province_code='VI')
     or exists(select 1 from public.network_it_istat_import_staging
               where batch_id=p_batch_id and (
                 nullif(btrim(municipality_name),'') is null
                 or nullif(btrim(municipality_normalized),'') is null
                 or nullif(btrim(province_name),'') is null
                 or nullif(btrim(region_name),'') is null
               ))
     or exists(select 1 from (
           select region_code from public.network_it_istat_import_staging
           where batch_id=p_batch_id group by region_code
           having count(distinct region_name)<>1
         ) mixed)
  then raise exception 'ISTAT batch lacks canonical 2026 reference or has inconsistent geography'
       using errcode='22023'; end if;

  update public.network_it_municipalities set is_current=false where is_current;
  insert into public.network_it_municipalities (
    istat_code,municipality_name,municipality_normalized,province_code,
    province_name,region_code,region_name,reference_date,source_url,is_current
  )
  select s.istat_code,s.municipality_name,s.municipality_normalized,s.province_code,
         s.province_name,s.region_code,s.region_name,v_batch.reference_date,
         v_batch.source_url,true
  from public.network_it_istat_import_staging s
  where s.batch_id=p_batch_id
  on conflict (istat_code) do update set
    municipality_name=excluded.municipality_name,
    municipality_normalized=excluded.municipality_normalized,
    province_code=excluded.province_code,province_name=excluded.province_name,
    region_code=excluded.region_code,region_name=excluded.region_name,
    reference_date=excluded.reference_date,source_url=excluded.source_url,is_current=true;

  update public.network_it_istat_import_batches set status='activated',activated_at=now()
  where id=p_batch_id;
  return jsonb_build_object('status','activated','batch_id',p_batch_id,'municipalities',v_rows,
                            'regions',v_regions,'source_sha256',v_batch.file_sha256);
end $$;
revoke all on function public.netux3a_activate_istat_import(uuid) from public,anon,authenticated;
grant execute on function public.netux3a_activate_istat_import(uuid) to service_role;

-- Correct only the underlying reference matcher; no change to published facilities.
create or replace function public.crawl_it4_match_municipality(p_city text,p_province_code text)
returns table(istat_code text,municipality_name text,province_code text,region_name text,reference_date date)
language sql stable security invoker set search_path=''
as $$
 select m.istat_code,m.municipality_name,m.province_code,m.region_name,m.reference_date
 from public.network_it_municipalities m
 where m.is_current and p_city is not null and p_province_code ~ '^[A-Za-z]{2}$'
   and m.municipality_normalized=lower(btrim(regexp_replace(p_city,'[[:space:]]+',' ','g')))
   and m.province_code=upper(p_province_code)
 order by m.istat_code limit 2;
$$;
revoke all on function public.crawl_it4_match_municipality(text,text) from public,anon,authenticated;
grant execute on function public.crawl_it4_match_municipality(text,text) to service_role;

alter table public.network_it_facility_geo_reviews
 add column if not exists evidence_snippet text;
comment on function public.netux3a_activate_istat_import(uuid) is
 'Service-role-only atomic activation of 7894 ISTAT 2026 municipalities. No company/facility mutation; sourced from official ISTAT permalink.';
